// Normaliza 1 ou N PDFs em itens individuais com chave binária consistente.
// Quando o form recebe múltiplos arquivos, as chaves ficam Fatura_PDF_0, Fatura_PDF_1...
// Este nó cria um item separado por PDF, todos com chave 'pdf_arquivo'.
const formJson = $input.first().json;
const binary   = $input.first().binary || {};

const pdfKeys = Object.keys(binary).filter(k => {
  const b = binary[k];
  return b && (
    (b.mimeType  || '').includes('pdf') ||
    (b.fileExtension || '') === 'pdf'   ||
    k.toLowerCase().includes('fatura') ||
    k.toLowerCase().includes('pdf')
  );
});

if (pdfKeys.length === 0) {
  throw new Error('Nenhum arquivo PDF encontrado no upload. Verifique se o arquivo é .pdf.');
}

// Um item por PDF; chave binária normalizada para 'pdf_arquivo'
return pdfKeys.map((k, idx) => ({
  json: {
    ...formJson,
    _arquivo_nome:  binary[k].fileName || k,
    _arquivo_index: idx,
    _total_arquivos: pdfKeys.length
  },
  binary: { pdf_arquivo: binary[k] }
}));

const resposta = $input.first().json.content?.[0]?.text || '';
let dados;
try {
  const m = resposta.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('JSON não encontrado');
  dados = JSON.parse(m[0]);
} catch(e) {
  return [{ json: { erro: true, msg: e.message, raw: resposta.substring(0,300) } }];
}

const mMap = { 'janeiro':'Janeiro','fevereiro':'Fevereiro','março':'Março','marco':'Março','abril':'Abril','maio':'Maio','junho':'Junho','julho':'Julho','agosto':'Agosto','setembro':'Setembro','outubro':'Outubro','novembro':'Novembro','dezembro':'Dezembro' };
const mesForm  = $('Formulário – Upload').first().json['Mês (opcional – ex: Abril)'] || '';
const mes      = mesForm || mMap[(dados.mes||'').toLowerCase().trim()] || dados.mes || 'Indefinido';
const email    = $('Formulário – Upload').first().json['Seu e-mail'] || '';
const banco    = dados.banco || 'N/A';

const lancamentos = (dados.lancamentos||[]).map(l => ({
  mes, banco,
  data:            l.data||'',
  descricao:       (l.descricao||'').substring(0,50),
  categoria:       l.categoria||'Outros',
  tipo:            l.tipo||'Despesa',
  valor:           parseFloat(l.valor)||0,
  forma_pagamento: l.forma_pagamento||'',
  cartao:          l.cartao||banco,
  parcelas:        parseInt(l.parcelas)||1,
  observacoes:     l.observacoes||''
}));

const tot_desp = lancamentos.filter(l=>l.tipo==='Despesa').reduce((s,l)=>s+l.valor,0);
const tot_rec  = lancamentos.filter(l=>l.tipo==='Receita').reduce((s,l)=>s+l.valor,0);

const por_cat = {};
lancamentos.forEach(l=>{ if(l.tipo==='Despesa') por_cat[l.categoria]=(por_cat[l.categoria]||0)+l.valor; });
const top_cat = Object.entries(por_cat).sort((a,b)=>b[1]-a[1]).slice(0,5);

const csvH = 'Data,Descrição,Categoria,Tipo,Valor (R$),Forma Pagto,Cartão,Parcelas,Observações';
const csvL = lancamentos.map(l=>`"${l.data}","${l.descricao}","${l.categoria}","${l.tipo}","${l.valor.toFixed(2).replace('.',',')}","${l.forma_pagamento}","${l.cartao}","${l.parcelas}","${l.observacoes}"`);
const csv  = [csvH,...csvL].join('\n');

const topHTML = top_cat.map(([c,v])=>`<tr><td style="padding:6px 12px;border-bottom:1px solid #eee">${c}</td><td style="padding:6px 12px;border-bottom:1px solid #eee;text-align:right">R$ ${v.toFixed(2).replace('.',',')}</td></tr>`).join('');
const linhasHTML = lancamentos.map(l=>`<tr><td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.data}</td><td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.descricao}</td><td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.categoria}</td><td style="color:${l.tipo==='Receita'?'#16a34a':'#dc2626'};padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.tipo}</td><td style="padding:5px 8px;border-bottom:1px solid #f0f0f0;text-align:right;font-weight:600">R$ ${l.valor.toFixed(2).replace('.',',')}</td><td style="padding:5px 8px;border-bottom:1px solid #f0f0f0">${l.cartao}</td></tr>`).join('');

const html = `<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="font-family:Arial,sans-serif;max-width:800px;margin:0 auto;padding:20px"><div style="background:#1e1e2e;color:#fff;padding:24px;border-radius:12px;margin-bottom:20px"><h1 style="margin:0 0 4px">Controle Financeiro</h1><p style="margin:0;color:#a0a0c0">${banco} – ${mes}</p></div><div style="display:flex;gap:12px;margin-bottom:20px;flex-wrap:wrap"><div style="flex:1;min-width:140px;background:#dcfce7;border-radius:8px;padding:14px"><div style="font-size:11px;color:#166534;font-weight:600">RECEITAS</div><div style="font-size:20px;font-weight:700;color:#16a34a">R$ ${tot_rec.toFixed(2).replace('.',',')}</div></div><div style="flex:1;min-width:140px;background:#fee2e2;border-radius:8px;padding:14px"><div style="font-size:11px;color:#991b1b;font-weight:600">DESPESAS</div><div style="font-size:20px;font-weight:700;color:#dc2626">R$ ${tot_desp.toFixed(2).replace('.',',')}</div></div><div style="flex:1;min-width:140px;background:#ede9fe;border-radius:8px;padding:14px"><div style="font-size:11px;color:#5b21b6;font-weight:600">SALDO</div><div style="font-size:20px;font-weight:700;color:#7c3aed">R$ ${(tot_rec-tot_desp).toFixed(2).replace('.',',')}</div></div><div style="flex:1;min-width:140px;background:#fef9c3;border-radius:8px;padding:14px"><div style="font-size:11px;color:#854d0e;font-weight:600">LANÇAMENTOS</div><div style="font-size:20px;font-weight:700;color:#ca8a04">${lancamentos.length}</div></div></div><h2 style="font-size:14px;margin-bottom:8px">Top Categorias</h2><table style="width:100%;border-collapse:collapse;margin-bottom:20px;background:#f9f9f9;border-radius:8px;overflow:hidden">${topHTML}</table><h2 style="font-size:14px;margin-bottom:4px">Lançamentos</h2><p style="font-size:12px;color:#666;margin-bottom:8px">CSV em anexo para importar no Excel.</p><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#1e1e2e;color:#fff"><th style="padding:7px;text-align:left">Data</th><th style="padding:7px;text-align:left">Descrição</th><th style="padding:7px;text-align:left">Categoria</th><th style="padding:7px;text-align:left">Tipo</th><th style="padding:7px;text-align:right">Valor</th><th style="padding:7px;text-align:left">Cartão</th></tr></thead><tbody>${linhasHTML}</tbody></table></body></html>`;

return [{ json: { mes, email, banco, lancamentos, tot_desp, tot_rec, csv, html, qtd: lancamentos.length, top_cat } }];

// Recebe diretamente o item do 'Parsear' – 1 item por PDF
const dados = $input.first().json;
const csv   = dados.csv;
const mes   = dados.mes;
const item  = { json: dados, binary: {} };
item.binary.csvFile = await this.helpers.prepareBinaryData(
  Buffer.from('\uFEFF' + csv, 'utf-8'),
  `lancamentos_${(mes||'mes').toLowerCase().replace(/ /g,'_')}.csv`,
  'text/csv'
);
return [item];
